def best_word(board, values):
    best = ''
    best_score = 0

    for row in range(len(board)):
        for col in range(len(board[row])):
            for dr, dc in directions:
                row2 = row + dr
                col2 = col + dc
                word = board[row][col] + board[row2][col2]
                score = values[word[0]] + values[word[1]]

                if score > best_score:
                    best = word
                    best_score = score

    return best

