column85:
def most_common_letter(board):
    counts = {}
    for row in board:
        for letter in row:
            counts[letter] = counts.get(letter, 0) + 1

    best_letter = None
    for letter in counts:
        if (best_letter is None or counts[letter] > counts[best_letter]
                or (counts[letter] == counts[best_letter] and letter < best_letter)):
            best_letter = letter
    return best_letter

column87:
def best_word(board, values):
    directions = ((-1, 0), (1, 0), (0, -1), (0, 1))
    rows = len(board)
    cols = len(board[0])
    best = None
    best_value = -1

    for r1 in range(rows):
        for c1 in range(cols):
            for dr1, dc1 in directions:
                r2, c2 = r1 + dr1, c1 + dc1
                if 0 <= r2 < rows and 0 <= c2 < cols:
                    for dr2, dc2 in directions:
                        r3, c3 = r2 + dr2, c2 + dc2
                        if (0 <= r3 < rows and 0 <= c3 < cols
                                and (r3, c3) != (r1, c1)):
                            word = board[r1][c1] + board[r2][c2] + board[r3][c3]
                            word_value = sum(values[letter] for letter in word)
                            if word_value > best_value:
                                best = word
                                best_value = word_value
    return best
